-- Test-only schema: cruise_providers / cruise_offers with the live column types (PostgREST OpenAPI, 2026-10-28)
-- and app_cruise_offer_cards as defined by 20261021120000_offer_disciplines (the live view since 2026-10-21).
CREATE TABLE cruise_providers (
  id uuid,
  provider_id uuid,
  name text,
  root_domain text,
  website_url text,
  primary_country text,
  primary_region text,
  description text,
  trip_types text[],
  languages text[],
  discovery_source text,
  contact_email text,
  contact_form_url text,
  whatsapp text,
  phone text,
  status text,
  duplicate_of uuid,
  notes text,
  last_verified_at timestamp with time zone,
  verified_at timestamp with time zone,
  vessel_name text,
  vessel_type text,
  passenger_capacity integer,
  cabin_count integer,
  typical_duration_days integer,
  home_port text,
  itinerary_notes text,
  price_per_person_eur integer,
  manually_verified boolean,
  created_at timestamp with time zone,
  updated_at timestamp with time zone,
  bstoked_url text,
  bstoked_rating numeric,
  bstoked_review_count integer,
  tripadvisor_url text,
  tripadvisor_rating numeric,
  tripadvisor_review_count integer,
  reviews_checked_at timestamp with time zone,
  review_match_notes text,
  google_url text,
  google_rating numeric,
  google_review_count integer,
  avg_rating numeric,
  email_preferences_token uuid,
  transactional_email_opted_out_at timestamp with time zone,
  future_email_opted_in_at timestamp with time zone
);
CREATE TABLE cruise_offers (
  id uuid,
  cruise_provider_id uuid,
  title text,
  slug text,
  source_url text,
  continent text,
  country text,
  region text,
  countries text[],
  departure_port text,
  itinerary_spots jsonb,
  vessel_name text,
  vessel_type text,
  booking_modes text[],
  beginner_friendly boolean,
  kite_lessons boolean,
  equipment_rental boolean,
  season_text text,
  season_start_month smallint,
  season_end_month smallint,
  duration_days integer,
  dates jsonb,
  pricing jsonb,
  price_from_eur integer,
  currency text,
  summary text,
  images jsonb,
  extraction_confidence text,
  manually_verified boolean,
  created_at timestamp with time zone,
  updated_at timestamp with time zone,
  source_text text,
  is_reseller boolean,
  operated_by text,
  skill_levels text[],
  water_conditions text[],
  wind_strength text[],
  included_services text[],
  optional_services text[],
  comfort_level text,
  suitable_for_non_kiters boolean,
  family_friendly boolean,
  accommodation text,
  meal_plan text,
  capacity_guests integer,
  cabin_count integer,
  price_confidence text,
  duplicate_of uuid,
  hero_video_url text,
  price_pp_cabin integer,
  price_pp_cabin_currency text,
  price_charter_week integer,
  price_charter_week_currency text,
  price_basis_note text,
  rooms jsonb,
  disciplines text[]
);
CREATE OR REPLACE VIEW public.app_cruise_offer_cards
WITH (security_invoker = true)
AS
select
  c.id as offer_id,
  c.title,
  c.slug,
  c.source_url,
  c.continent,
  c.country,
  c.region,
  c.countries,
  c.departure_port,
  c.itinerary_spots,
  c.vessel_name,
  c.vessel_type,
  c.booking_modes,
  c.beginner_friendly,
  c.kite_lessons,
  c.equipment_rental,
  c.season_text,
  c.duration_days,
  c.pricing,
  c.price_from_eur,
  c.currency,
  c.summary,
  c.images,
  c.extraction_confidence,
  c.manually_verified,
  c.is_reseller,
  c.operated_by,
  c.updated_at,
  p.id as provider_id,
  p.name as provider_name,
  p.root_domain as provider_root_domain,
  p.website_url as provider_website_url,
  p.contact_email as provider_contact_email,
  p.contact_form_url as provider_contact_form_url,
  p.languages as provider_languages,
  p.trip_types as provider_trip_types,
  p.passenger_capacity as provider_passenger_capacity,
  p.cabin_count as provider_cabin_count,
  p.verified_at as provider_verified_at,
  p.last_verified_at as provider_last_verified_at,
  c.skill_levels,
  c.included_services,
  c.optional_services,
  c.comfort_level,
  c.suitable_for_non_kiters,
  c.family_friendly,
  c.accommodation,
  c.meal_plan,
  c.capacity_guests,
  c.cabin_count as offer_cabin_count,
  c.price_confidence as offer_price_confidence,
  c.season_start_month,
  c.season_end_month,
  c.dates,
  p.bstoked_url as provider_bstoked_url,
  p.bstoked_rating as provider_bstoked_rating,
  p.bstoked_review_count as provider_bstoked_review_count,
  p.tripadvisor_url as provider_tripadvisor_url,
  p.tripadvisor_rating as provider_tripadvisor_rating,
  p.tripadvisor_review_count as provider_tripadvisor_review_count,
  p.reviews_checked_at as provider_reviews_checked_at,
  c.hero_video_url,
  p.google_url as provider_google_url,
  p.google_rating as provider_google_rating,
  p.google_review_count as provider_google_review_count,
  p.avg_rating as provider_avg_rating,
  c.price_pp_cabin,
  c.price_pp_cabin_currency,
  c.price_charter_week,
  c.price_charter_week_currency,
  c.price_basis_note,
  -- appended 2026-09-29 (cabin / room types)
  c.rooms,
  -- appended 2026-10-21 (sports, MartinMarzi/KiteCruiseScout#239)
  c.disciplines
from public.cruise_offers c
left join public.cruise_providers p on p.id = c.cruise_provider_id
where c.duplicate_of is null
  and coalesce(p.status, 'new') not in ('dead', 'duplicate')
  -- Reseller-Angebote hart inaktiv (Aaron 2026-07-10): nie im Produkt zeigen
  and coalesce(c.is_reseller, false) = false;
